export default function (event) {
  // Return the event to keep it, or nothing to drop it.
  const email = event.context?.traits?.email ?? ''
  if (email.endsWith('@sfere.io')) return
  if (event.context?.userAgent?.includes('HeadlessChrome')) return
  return event
}

const RATES = { SAR: 1, USD: 3.75, AED: 1.02 }

export default function (event) {
  const currency = event.properties?.currency
  const revenue = event.properties?.revenue
  if (!currency || typeof revenue !== 'number') return event
  const rate = RATES[currency]
  if (!rate) return event
  return {
    ...event,
    properties: {
      ...event.properties,
      revenue_sar: Math.round(revenue * rate * 100) / 100
    }
  }
}

export default function (event) {
  const url = event.context?.page?.url
  if (!url) return event
  const params = new URL(url).searchParams
  const campaign = {
    source: params.get('utm_source'),
    medium: params.get('utm_medium'),
    name: params.get('utm_campaign')
  }
  if (!campaign.source && !campaign.name) return event
  return { ...event, context: { ...event.context, campaign } }
}
